    /// FNCOLND: `end` used as column index without explicit dimension specification.
    fn check_fncolnd(&self, tree: &tree_sitter::Tree, _source: &str) -> Vec<Diagnostic> {
        if !self.is_check_enabled("FNCOLND") {
            return Vec::new();
